import{_ as i,c as e,o,a0 as a}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Introduzione al Mental Game - Guida per i partecipanti","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/it/participant-guide.md","filePath":"public/downloads/it/participant-guide.md"}');const r=i({name:"public/downloads/it/participant-guide.md"},[["render",function(i,t,r,l,n,s){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="introduzione-al-mental-game-guida-per-i-partecipanti" tabindex="-1">Introduzione al Mental Game - Guida per i partecipanti <a class="header-anchor" href="#introduzione-al-mental-game-guida-per-i-partecipanti" aria-label="Permalink to &quot;Introduzione al Mental Game - Guida per i partecipanti&quot;">​</a></h1><p><strong>Accademia di bocce</strong><em>Sviluppo dei giocatori d&#39;élite</em></p><hr><h2 id="benvenuto" tabindex="-1">Benvenuto <a class="header-anchor" href="#benvenuto" aria-label="Permalink to &quot;Benvenuto&quot;">​</a></h2><p>Oggi imparerai tecniche pratiche di mental game per migliorare le tue prestazioni nel gioco delle bocce.</p><h3 id="cosa-imparerai" tabindex="-1">Cosa imparerai <a class="header-anchor" href="#cosa-imparerai" aria-label="Permalink to &quot;Cosa imparerai&quot;">​</a></h3><ul><li>Perché l&#39;allenamento mentale è importante per i giocatori d&#39;élite</li><li>La differenza tra &quot;modalità tecnica&quot; e &quot;modalità di flusso&quot;</li><li>Come riconoscere e gestire il tuo critico interiore</li><li>Semplici tecniche per la gestione della pressione</li><li>Una routine di base prima del tiro</li></ul><hr><h2 id="lo-stato-di-zona-flusso" tabindex="-1">Lo stato di zona/flusso <a class="header-anchor" href="#lo-stato-di-zona-flusso" aria-label="Permalink to &quot;Lo stato di zona/flusso&quot;">​</a></h2><h3 id="che-cos-39-e-flow" tabindex="-1">Che cos&#39;è Flow? <a class="header-anchor" href="#che-cos-39-e-flow" aria-label="Permalink to &quot;Che cos&amp;#39;è Flow?&quot;">​</a></h3><p>Il flusso è quello stato magico in cui:</p><ul><li>Tutto sembra senza sforzo</li><li>Il tempo sembra rallentare</li><li>Non stai pensando, stai solo giocando</li><li>La tua tecnica funziona perfettamente</li></ul><h3 id="due-modalita-della-mente" tabindex="-1">Due modalità della mente <a class="header-anchor" href="#due-modalita-della-mente" aria-label="Permalink to &quot;Due modalità della mente&quot;">​</a></h3><p><strong>Modalità di pianificazione (analitica)</strong></p><ul><li>Analisi del terreno</li><li>Scegliere la strategia</li><li>Decidere lo scatto</li><li>Valutazione dei rischi</li></ul><p><strong>Modalità di esecuzione (flusso)</strong></p><ul><li>Fidarsi del proprio corpo</li><li>Non pensare alla tecnica</li><li>Focus sul momento presente</li><li>Esecuzione automatica</li></ul><h3 id="l-39-interruttore" tabindex="-1">L&#39;interruttore <a class="header-anchor" href="#l-39-interruttore" aria-label="Permalink to &quot;L&amp;#39;interruttore&quot;">​</a></h3><p>L&#39;abilità chiave: <strong>passare dalla modalità di pianificazione a quella di esecuzione</strong></p><p><strong>Prima dello scatto:</strong> Analizza, pianifica, decidi <strong>Durante lo scatto:</strong> Fiducia, flusso, esecuzione</p><hr><h2 id="il-critico-interiore-contro-il-coach-interiore" tabindex="-1">Il critico interiore contro il coach interiore <a class="header-anchor" href="#il-critico-interiore-contro-il-coach-interiore" aria-label="Permalink to &quot;Il critico interiore contro il coach interiore&quot;">​</a></h2><h3 id="il-tuo-critico-interiore-dice" tabindex="-1">Il tuo critico interiore dice: <a class="header-anchor" href="#il-tuo-critico-interiore-dice" aria-label="Permalink to &quot;Il tuo critico interiore dice:&quot;">​</a></h3><ul><li>&quot;È stato terribile!&quot;</li><li>&quot;Sotto pressione, sbagli sempre&quot;</li><li>&quot;Tutti ti guardano fallire&quot;</li><li>&quot;Non sei abbastanza bravo&quot;</li></ul><h3 id="il-tuo-coach-interiore-dice" tabindex="-1">Il tuo coach interiore dice: <a class="header-anchor" href="#il-tuo-coach-interiore-dice" aria-label="Permalink to &quot;Il tuo coach interiore dice:&quot;">​</a></h3><ul><li>&quot;Cosa posso imparare da questo?&quot;</li><li>&quot;Prossimo colpo, nuovo inizio&quot;</li><li>&quot;Ho già fatto questo scatto prima&quot;</li><li>&quot;Fidati del processo&quot;</li></ul><h3 id="esercizio-di-riformulazione" tabindex="-1">Esercizio di riformulazione <a class="header-anchor" href="#esercizio-di-riformulazione" aria-label="Permalink to &quot;Esercizio di riformulazione&quot;">​</a></h3><p>Quando noti il tuo Critico Interiore:</p><ol><li><strong>Pausa</strong> - Riconosci il pensiero critico</li><li><strong>Riformula</strong> - Cosa direbbe il tuo allenatore?</li><li><strong>Reset</strong> - Fai 3 respiri</li><li><strong>Rimetti a fuoco</strong> - Prossimo scatto</li></ol><hr><h2 id="strumenti-pratici" tabindex="-1">Strumenti pratici <a class="header-anchor" href="#strumenti-pratici" aria-label="Permalink to &quot;Strumenti pratici&quot;">​</a></h2><h3 id="_3-reset-del-respiro" tabindex="-1">3-Reset del respiro <a class="header-anchor" href="#_3-reset-del-respiro" aria-label="Permalink to &quot;3-Reset del respiro&quot;">​</a></h3><p>Usalo dopo aver commesso degli errori o quando ti senti sotto pressione:</p><ol><li><strong>Respiro 1:</strong> Nota la tensione (dove la senti?)</li><li><strong>Respiro 2:</strong> Rilascia la tensione (lasciala andare)</li><li><strong>Respiro 3:</strong> Riconcentrati sul presente (questo scatto, questo momento)</li></ol><h3 id="routine-pre-tiro" tabindex="-1">Routine pre-tiro <a class="header-anchor" href="#routine-pre-tiro" aria-label="Permalink to &quot;Routine pre-tiro&quot;">​</a></h3><p>Crea coerenza con una semplice routine:</p><ol><li><strong>Visualizza</strong> - Visualizza lo scatto nella tua mente</li><li><strong>Respira</strong> - Un respiro profondo</li><li><strong>Ancora</strong> - Tocca la tua boccia, senti il peso</li><li><strong>Esegui</strong> - Fidati e lancia</li></ol><h3 id="protocollo-di-recupero-degli-errori" tabindex="-1">Protocollo di recupero degli errori <a class="header-anchor" href="#protocollo-di-recupero-degli-errori" aria-label="Permalink to &quot;Protocollo di recupero degli errori&quot;">​</a></h3><p>Dopo un brutto tiro:</p><ol><li><strong>Riconoscimento</strong> - &quot;Non è andato come previsto&quot;</li><li><strong>Rilascio</strong> - Ripristino fisico (scuotilo di dosso, cammina)</li><li><strong>Riconcentrati</strong> - &quot;Il prossimo colpo è una nuova opportunità&quot;</li><li><strong>Esegui</strong> - Fidati della tua routine</li></ol><hr><h2 id="il-tuo-piano-d-39-azione" tabindex="-1">Il tuo piano d&#39;azione <a class="header-anchor" href="#il-tuo-piano-d-39-azione" aria-label="Permalink to &quot;Il tuo piano d&amp;#39;azione&quot;">​</a></h2><h3 id="questa-settimana" tabindex="-1">Questa settimana <a class="header-anchor" href="#questa-settimana" aria-label="Permalink to &quot;Questa settimana&quot;">​</a></h3><p>Scegli UNA tecnica da praticare:</p><ul><li>[ ] 3-Reset del respiro dopo ogni errore</li><li>[ ] Routine pre-tiro su ogni lancio</li><li>[ ] Riformula un pensiero del Critico Interiore per sessione</li><li>[ ] Esercitarsi a passare dalla modalità di pianificazione a quella di esecuzione</li></ul><h3 id="tieni-traccia-dei-tuoi-progressi" tabindex="-1">Tieni traccia dei tuoi progressi <a class="header-anchor" href="#tieni-traccia-dei-tuoi-progressi" aria-label="Permalink to &quot;Tieni traccia dei tuoi progressi&quot;">​</a></h3><p>Avviso:</p><ul><li>Quando ti senti più in flusso?</li><li>Cosa attiva il tuo Critico Interiore?</li><li>Quale tecnica ti è più utile?</li><li>Come cambiano le tue prestazioni?</li></ul><hr><h2 id="risorse-e-prossimi-passi" tabindex="-1">Risorse e prossimi passi <a class="header-anchor" href="#risorse-e-prossimi-passi" aria-label="Permalink to &quot;Risorse e prossimi passi&quot;">​</a></h2><h3 id="continua-ad-apprendere" tabindex="-1">Continua ad apprendere <a class="header-anchor" href="#continua-ad-apprendere" aria-label="Permalink to &quot;Continua ad apprendere&quot;">​</a></h3><ul><li><strong>The Zone</strong> - Immersione profonda negli stati di flusso</li><li><strong>Forza mentale</strong> - Gestione avanzata della pressione</li><li><strong>Modello di obiettivo</strong> - Struttura il tuo sviluppo</li><li><strong>Modello di diario</strong> - Tieni traccia dei tuoi progressi</li></ul><h3 id="pratica-ogni-giorno" tabindex="-1">Pratica ogni giorno <a class="header-anchor" href="#pratica-ogni-giorno" aria-label="Permalink to &quot;Pratica ogni giorno&quot;">​</a></h3><ul><li>5 minuti di respirazione consapevole</li><li>Visualizza i tiri riusciti</li><li>Esercitati con la routine pre-tiro</li><li>Riformulare i pensieri negativi</li></ul><hr><h2 id="punti-chiave" tabindex="-1">Punti chiave <a class="header-anchor" href="#punti-chiave" aria-label="Permalink to &quot;Punti chiave&quot;">​</a></h2><ol><li><strong>Lo stato di flusso è accessibile</strong> - Puoi imparare a inserirlo in modo più coerente</li><li><strong>La tua voce interiore è importante</strong> - Allenati, non criticare</li><li><strong>Funzionano strumenti semplici</strong>: 3 respiri, una routine, un reset</li><li><strong>La pratica è la chiave</strong> - Le capacità mentali necessitano di allenamento come le capacità tecniche</li></ol><hr><p><strong>Ricorda:</strong> L&#39;allenamento mentale non riguarda il pensiero positivo. Riguarda tecniche pratiche che ti aiutano a raggiungere le massime prestazioni sotto pressione.</p><hr><p><em>Visita carreau.app per maggiori risorse</em><em>Accademia di bocce - Sviluppo dei giocatori d&#39;élite</em></p>',61)])])}]]);export{t as __pageData,r as default};
